    two = -1
    for i in range(n):
        num, skill = arr[i]
        num = int(num)
        if '1' in skill:
            if skill.find('1') == 0:
                one = max(one, num)
            else:
                two = max(two, num)
        if '11' in skill:
            heapq.heappush(heap, num)
    if one!= -1 and two!= -1:
        return one + two
    elif one == -1 and two == -1:
        return -1
    elif one == -1:
        if len(heap) == 0:
            return -1
        else:
            return heap[0]
    else:
        if len(heap) == 0:
            return -1
        else:
            return one + heapq.heappop(heap)

