def solve():
    n = int(input())
    slices = []
    for _ in range(n):
        slices.append(tuple(map(int, input().split())))
    heapq.heapify(slices)
    res = 2 * sum(a + b for a, b in slices)
    left = 0
    while len(slices) > 1:
        a1, b1 = heapq.heappop(slices)
        a2, b2 = heapq.heappop(slices)
        if a1 <= a2:
            res += a1 * 2
            if b1 > b2:
                heapq.heappush(slices, (b1, a2 + b2))
            elif b2 > b1:
                heapq.heappush(slices, (b2, a1 + b1))
            else:
                heapq.heappush(slices, (b2, a1))
        else:
            res += b1 * 2
            if a1 > a2:
                heapq.heappush(slices, (a1, a2 + b2))
            elif a2 > a1:
                heapq.heappush(slices, (a2, a1 + b1))
            else:
                heapq.heappush(slices, (a2, b1))
    a1, b1 = slices[0]
    res += a1 * 2
    return res

