class MaxHeap:
    def __init__(self):
        self.maxHeap = []
        self.minHeap = []

    def push(self, x):
        heapq.heappush(self.maxHeap, -x)
        heapq.heappush(self.minHeap, x)

    def popMax(self):
        top = -heapq.heappop(self.maxHeap)
        if len(self.maxHeap) < len(self.minHeap):
            heapq.heappush(self.maxHeap, -self.minHeap[0])
            heapq.heappop(self.minHeap)
        return top

    def popMin(self):
        top = heapq.heappop(self.minHeap)
        if len(self.minHeap) < len(self.maxHeap):
            heapq.heappush(self.minHeap, -self.maxHeap[0])
            heapq.heappop(self.maxHeap)
        return top

